\/gallery\\\"><img class=\\\"wp-image-17\\\" src=\\\"http:\\/\\/dahandaniel.com\\/wp-content\\/uploads\\/2023\\/10\\/elegant_guitar_floor_cover-1024x680.jpeg\\\" alt=\\\"\\\" \\/><\\/a><\\/figure>\\n<!-- \\/wp:image --><!-- wp:image {\\\"id\\\":16,\\\"sizeSlug\\\":\\\"large\\\",\\\"linkDestination\\\":\\\"custom\\\"} -->\\n<figure class=\\\"wp-block-image size-large\\\"><a href=\\\"\\/galley\\\"><img class=\\\"wp-image-16\\\" src=\\\"http:\\/\\/dahandaniel.com\\/wp-content\\/uploads\\/2023\\/10\\/chill_field_cover-1024x610.jpeg\\\" alt=\\\"\\\" \\/><\\/a><\\/figure>\\n<!-- \\/wp:image --><!-- wp:image {\\\"id\\\":14,\\\"sizeSlug\\\":\\\"large\\\",\\\"linkDestination\\\":\\\"custom\\\"} -->\\n<figure class=\\\"wp-block-image size-large\\\"><a href=\\\"\\/gallery\\\"><img class=\\\"wp-image-14\\\" src=\\\"http:\\/\\/dahandaniel.com\\/wp-content\\/uploads\\/2023\\/10\\/athletic_modeling_cover-1024x682.jpeg\\\" alt=\\\"\\\" \\/><\\/a><\\/figure>\\n<!-- \\/wp:image --><!-- wp:image {\\\"id\\\":21,\\\"sizeSlug\\\":\\\"large\\\",\\\"linkDestination\\\":\\\"custom\\\"} -->\\n<figure class=\\\"wp-block-image size-large\\\"><a href=\\\"gallery\\\"><img class=\\\"wp-image-21\\\" src=\\\"http:\\/\\/dahandaniel.com\\/wp-content\\/uploads\\/2023\\/10\\/the_drape_modeling_cover-1024x771.jpeg\\\" alt=\\\"\\\" \\/><\\/a><\\/figure>\\n<!-- \\/wp:image --><!-- wp:image {\\\"id\\\":19,\\\"sizeSlug\\\":\\\"large\\\",\\\"linkDestination\\\":\\\"custom\\\"} -->\\n<figure class=\\\"wp-block-image size-large\\\"><a href=\\\"\\/gallery\\\"><img class=\\\"wp-image-19\\\" src=\\\"http:\\/\\/dahandaniel.com\\/wp-content\\/uploads\\/2023\\/10\\/guitar_cover-1024x685.jpeg\\\" alt=\\\"\\\" \\/><\\/a><\\/figure>\\n<!-- \\/wp:image --><!-- wp:image {\\\"id\\\":43,\\\"sizeSlug\\\":\\\"large\\\",\\\"linkDestination\\\":\\\"custom\\\"} -->\\n<figure class=\\\"wp-block-image size-large\\\"><a href=\\\"\\/gallery\\\"><img class=\\\"wp-image-43\\\" src=\\\"http:\\/\\/dahandaniel.com\\/wp-content\\/uploads